import errno, os, pty, subprocess
for args in [['--paging=never'], ['--paging=never', '--plain'], ['--plain', '--paging=never'], ['--paging=always', '--plain']]:
    master, slave = pty.openpty()
    env = dict(os.environ, BAT_PAGER='echo pager-output', TERM='xterm', BAT_CONFIG_PATH='/dev/null')
    for key in ['BAT_OPTS', 'BAT_PAGING', 'BAT_STYLE']:
        env.pop(key, None)
    child = subprocess.Popen(['target/debug/bat', '--no-config', *args, 'tests/examples/test.txt'], stdin=subprocess.DEVNULL, stdout=slave, stderr=slave, env=env)
    os.close(slave)
    output = b''
    while True:
        try:
            chunk = os.read(master, 4096)
        except OSError as error:
            if error.errno != errno.EIO:
                raise
            break
        if not chunk:
            break
        output += chunk
    os.close(master)
    print(args, 'exit=', child.wait(), 'output=', repr(output))
PY

