+mod tests {
+    use super::*;
+
+    #[test]
+    fn paging_plain_options_preserve_style_and_precedence() {
+        for interactive_output in [false, true] {
+            let automatic = if interactive_output {
+                PagingMode::QuitIfOneScreen
+            } else {
+                PagingMode::Never
+            };
+            let cases: &[(&[&str], PagingMode)] = &[
+                (&["--plain"], automatic),
+                (&["--paging=never", "--plain"], PagingMode::Never),
+                (&["--plain", "--paging=never"], PagingMode::Never),
+                (&["--paging=never", "-p"], PagingMode::Never),
+                (&["-p", "--paging=never"], PagingMode::Never),
+                (&["--paging=always", "--plain"], PagingMode::Always),
+                (&["--plain", "--paging=always"], PagingMode::Always),
+                (&["--paging=auto", "--plain"], automatic),
+                (&["--plain", "--paging=auto"], automatic),
+                (&["-pp"], PagingMode::Never),
+                (&["--plain", "--plain"], PagingMode::Never),
+                (&["--paging=always", "-pp"], PagingMode::Never),
+                (&["-pp", "--paging=always"], PagingMode::Always),
+                (&["--paging=auto", "-pp"], PagingMode::Never),
+                (&["-pp", "--paging=auto"], automatic),
+                (&["--paging=always", "--plain", "--plain"], PagingMode::Never),
+                (&["--plain", "--plain", "--paging=always"], PagingMode::Always),
+                (&["--no-paging", "--plain"], PagingMode::Never),
+                (&["--plain", "--no-paging"], PagingMode::Never),
+                (&["-pp", "--paging=always", "-P"], PagingMode::Never),
+                (&["-pp", "-P", "--paging=always"], PagingMode::Always),
+            ];
+
+            for &(args, expected) in cases {
+                let app = App {
+                    matches: clap_app::build_app(interactive_output).get_matches_from(
+                        ["bat"].into_iter().chain(args.iter().copied()).chain(["tests/examples/test.txt"]),
+                    ),
+                    interactive_output,
+                };
+                let config = app.config(&app.inputs().unwrap()).unwrap();
+
+                assert_eq!(config.paging_mode, expected, "{args:?}, interactive={interactive_output}");
