+#[cfg(unix)]
+#[test]
+fn paging_plain_does_not_start_pager() {
+    use std::io::Read;
+
+    for args in [
+        ["--paging=never", "--plain"],
+        ["--plain", "--paging=never"],
+        ["--paging=never", "-p"],
+        ["-p", "--paging=never"],
+    ] {
+        let OpenptyResult { master, slave } = openpty(None, None).expect("Couldn't open pty.");
+        let mut master = File::from(master);
+        let mut child = bat_raw_command()
+            .args(args)
+            .arg("--pager=echo pager-output")
+            .arg("--color=never")
+            .arg("--decorations=always")
+            .arg("test.txt")
+            .stdin(Stdio::null())
+            .stdout(Stdio::from(File::from(slave)))
+            .stderr(Stdio::piped())
+            .spawn()
+            .expect("Failed to start.");
+
+        let status = child
+            .wait_timeout(CHILD_WAIT_TIMEOUT)
+            .expect("Error polling exit status.")
+            .expect("The child should have exited already.");
+        assert!(status.success());
+        child.wait_with_output().unwrap().assert().success().stderr("");
+
+        let mut output = [0; 13];
+        master.read_exact(&mut output).unwrap();
+        assert_eq!(&output, b"hello world\r\n", "{args:?}");
+    }
+}
